onClick:
{{
  Action_Supprimer_Materiel.run().then((res) => {
    if (res[0].total_lignes > 0) {
      showAlert('Machine archivée (présence d\'un historique lié).', 'info');
    } else {
      showAlert('Machine supprimée définitivement.', 'success');
    }

    closeModal('modal_delete_client');

    // Retour à la page d'où tu viens (client, atelier ou stock)
    navigateTo(
      appsmith.store.page_precedente || 'Détail Client', 
      appsmith.store.id_precedent ? { id: appsmith.store.id_precedent } : { id: Get_Materiel_Infos.data[0]?.ID_Client }
    );
  }).catch((err) => {
    showAlert('Erreur lors de la suppression : ' + err.message, 'error');
  });
}}
